import { expect, test } from "bun:test";

export function shippingFee(total: number, isMember: boolean): number {
	let fee = 10;
	if (isMember) fee = 5;
	if (total >= 100) fee = 0;
	return fee;
}

test("member with a large order pays no fee", () => {
	expect(shippingFee(150, true)).toBe(0);
});

